import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_cpp_source = r"""
#include <torch/extension.h>

torch::Tensor cute_triplet_margin_loss(
    torch::Tensor anchor,
    torch::Tensor positive,
    torch::Tensor negative,
    double margin);
"""


_cuda_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

__global__ void cute_triplet_margin_loss_kernel(
    const float* anchor_ptr,
    const float* positive_ptr,
    const float* negative_ptr,
    float* output_ptr,
    int batch,
    int dim,
    float margin)
{
    constexpr int warps_per_block = 8;
    const int tid = threadIdx.x;
    const int lane = tid & 31;
    const int warp = tid >> 5;
    const int grid_warps = gridDim.x * warps_per_block;
    float loss_sum = 0.0f;
    __shared__ float warp_losses[warps_per_block];

    for (int row = blockIdx.x * warps_per_block + warp;
         row < batch;
         row += grid_warps) {
        const float* anchor_row = anchor_ptr + static_cast<size_t>(row) * dim;
        const float* positive_row = positive_ptr + static_cast<size_t>(row) * dim;
        const float* negative_row = negative_ptr + static_cast<size_t>(row) * dim;
        const bool vector_aligned =
            ((reinterpret_cast<uintptr_t>(anchor_row) |
              reinterpret_cast<uintptr_t>(positive_row) |
              reinterpret_cast<uintptr_t>(negative_row)) & 0xF) == 0;
        float positive_sum = 0.0f;
        float negative_sum = 0.0f;

        for (int d = lane * 4; d < dim; d += 32 * 4) {
            if (vector_aligned && d + 3 < dim) {
                const float4 av = *reinterpret_cast<const float4*>(anchor_row + d);
                const float4 pv = *reinterpret_cast<const float4*>(positive_row + d);
                const float4 nv = *reinterpret_cast<const float4*>(negative_row + d);
                const float ap0 = av.x - pv.x + 1.0e-6f;
                const float ap1 = av.y - pv.y + 1.0e-6f;
                const float ap2 = av.z - pv.z + 1.0e-6f;
                const float ap3 = av.w - pv.w + 1.0e-6f;
                const float an0 = av.x - nv.x + 1.0e-6f;
                const float an1 = av.y - nv.y + 1.0e-6f;
                const float an2 = av.z - nv.z + 1.0e-6f;
                const float an3 = av.w - nv.w + 1.0e-6f;
                positive_sum = fmaf(ap0, ap0, positive_sum);
                positive_sum = fmaf(ap1, ap1, positive_sum);
                positive_sum = fmaf(ap2, ap2, positive_sum);
                positive_sum = fmaf(ap3, ap3, positive_sum);
                negative_sum = fmaf(an0, an0, negative_sum);
                negative_sum = fmaf(an1, an1, negative_sum);
                negative_sum = fmaf(an2, an2, negative_sum);
                negative_sum = fmaf(an3, an3, negative_sum);
            } else {
                for (int k = 0; k < 4 && d + k < dim; ++k) {
                    const float ap = anchor_row[d + k] - positive_row[d + k] + 1.0e-6f;
                    const float an = anchor_row[d + k] - negative_row[d + k] + 1.0e-6f;
                    positive_sum = fmaf(ap, ap, positive_sum);
                    negative_sum = fmaf(an, an, negative_sum);
                }
            }
        }

        for (int offset = 16; offset > 0; offset >>= 1) {
            positive_sum += __shfl_down_sync(0xffffffff, positive_sum, offset);
            negative_sum += __shfl_down_sync(0xffffffff, negative_sum, offset);
        }
        if (lane == 0) {
            loss_sum += fmaxf(
                sqrtf(positive_sum) - sqrtf(negative_sum) + margin,
                0.0f);
        }
    }

    if (lane == 0) {
        warp_losses[warp] = loss_sum;
    }
    __syncthreads();

    if (warp == 0) {
        float block_loss = (lane < warps_per_block) ? warp_losses[lane] : 0.0f;
        for (int offset = 16; offset > 0; offset >>= 1) {
            block_loss += __shfl_down_sync(0xffffffff, block_loss, offset);
        }
        if (lane == 0) {
            atomicAdd(output_ptr, block_loss / static_cast<float>(batch));
        }
    }
}
__global__ void cute_triplet_margin_loss_dim1_kernel(
    const float* anchor_ptr,
    const float* positive_ptr,
    const float* negative_ptr,
    float* output_ptr,
    int batch,
    float margin)
{
    const int tid = threadIdx.x;
    const int row = blockIdx.x * blockDim.x + tid;
    float loss = 0.0f;
    if (row < batch) {
        const float ap = anchor_ptr[row] - positive_ptr[row] + 1.0e-6f;
        const float an = anchor_ptr[row] - negative_ptr[row] + 1.0e-6f;
        const float positive_distance = sqrtf(ap * ap);
        const float negative_distance = sqrtf(an * an);
        loss = fmaxf(positive_distance - negative_distance + margin, 0.0f);
    }
    __shared__ float warp_losses[8];
    const int lane = tid & 31;
    const int warp = tid >> 5;
    for (int offset = 16; offset > 0; offset >>= 1) {
        loss += __shfl_down_sync(0xffffffff, loss, offset);
    }
    if (lane == 0) {
        warp_losses[warp] = loss;
    }
    __syncthreads();
    if (warp == 0) {
        float block_loss = (lane < 8) ? warp_losses[lane] : 0.0f;
        for (int offset = 16; offset > 0; offset >>= 1) {
            block_loss += __shfl_down_sync(0xffffffff, block_loss, offset);
        }
        if (lane == 0) {
            atomicAdd(output_ptr, block_loss / static_cast<float>(batch));
        }
    }
}
torch::Tensor cute_triplet_margin_loss(
    torch::Tensor anchor,
    torch::Tensor positive,
    torch::Tensor negative,
    double margin)
{
    TORCH_CHECK(anchor.is_cuda(), "anchor must be a CUDA tensor");
    TORCH_CHECK(positive.is_cuda(), "positive must be a CUDA tensor");
    TORCH_CHECK(negative.is_cuda(), "negative must be a CUDA tensor");
    TORCH_CHECK(anchor.scalar_type() == at::kFloat,
                "anchor must have dtype float32");
    TORCH_CHECK(positive.scalar_type() == at::kFloat,
                "positive must have dtype float32");
    TORCH_CHECK(negative.scalar_type() == at::kFloat,
                "negative must have dtype float32");
    TORCH_CHECK(anchor.dim() == 2 &&
                positive.dim() == 2 &&
                negative.dim() == 2,
                "inputs must be 2D tensors");
    TORCH_CHECK(anchor.sizes() == positive.sizes() &&
                anchor.sizes() == negative.sizes(),
                "all inputs must have identical shapes");
    TORCH_CHECK(anchor.size(0) > 0 && anchor.size(1) > 0,
                "inputs must be non-empty");
    auto anchor_contiguous = anchor.contiguous();
    auto positive_contiguous = positive.contiguous();
    auto negative_contiguous = negative.contiguous();
    const int batch = static_cast<int>(anchor.size(0));
    const int dim = static_cast<int>(anchor.size(1));
    auto output = torch::zeros({}, anchor.options());
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    constexpr int warps_per_block = 8;
    constexpr int threads = warps_per_block * 32;
     const int logical_blocks = (batch + warps_per_block - 1) / warps_per_block;
     cudaDeviceProp device_prop;
     TORCH_CHECK(cudaGetDeviceProperties(&device_prop, anchor.get_device()) == cudaSuccess,
                 "failed to query CUDA device properties");
     const int resident_blocks = device_prop.multiProcessorCount * 4;
     const int num_blocks = logical_blocks < resident_blocks ? logical_blocks : resident_blocks;
     if (dim == 1) {
         constexpr int specialized_threads = 256;
         const int specialized_blocks =
             (batch + specialized_threads - 1) / specialized_threads;
         cute_triplet_margin_loss_dim1_kernel<<<
             specialized_blocks, specialized_threads, 0, stream>>>(
             anchor_contiguous.data_ptr<float>(),
             positive_contiguous.data_ptr<float>(),
             negative_contiguous.data_ptr<float>(),
             output.data_ptr<float>(),
             batch,
             static_cast<float>(margin));
     } else {
         cute_triplet_margin_loss_kernel<<<num_blocks, threads, 0, stream>>>(
             anchor_contiguous.data_ptr<float>(),
             positive_contiguous.data_ptr<float>(),
             negative_contiguous.data_ptr<float>(),
             output.data_ptr<float>(),
             batch,
             dim,
             static_cast<float>(margin));
     }
     TORCH_CHECK(
         cudaGetLastError() == cudaSuccess,
         "CuTe triplet margin loss kernel launch failed");
    return output;
}
"""


_cute_ext = load_inline(
    name="cute_triplet_margin_loss_ext",
    cpp_sources=_cpp_source,
    cuda_sources=_cuda_source,
    functions=["cute_triplet_margin_loss"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, margin=1.0):
        super().__init__()
        self.margin = float(margin)

    def forward(self, anchor, positive, negative):
        return _cute_ext.cute_triplet_margin_loss(
            anchor,
            positive,
            negative,
            self.margin,
        )

